// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref, uint256 seedAmount, uint256 callValue) public {
        vm.assume(caller != address(0));
        vm.assume(ref != address(0));
        vm.assume(caller != ref);
        vm.assume(seedAmount > 0 && seedAmount <= 100000);
        vm.assume(callValue >= 0.001 ether && callValue <= 10 ether);

        // Seed the market
        c.seedMarket(seedAmount);

        // Get free kilos for both caller and ref
        vm.prank(caller);
        c.getFreeKilo();
        vm.prank(ref);
        c.getFreeKilo();

        // Buy some drugs for the caller
        vm.deal(caller, callValue);
        vm.prank(caller);
        c.buyDrugs{value: callValue}();

        // Record state before collectDrugs
        uint256 callerClaimedBefore = c.claimedDrugs(caller);
        uint256 refClaimedBefore = c.claimedDrugs(ref);

        // Call collectDrugs with ref as referral
        vm.prank(caller);
        c.collectDrugs(ref);

        // Check rule: caller's claimedDrugs becomes 0
        assertTrue(c.claimedDrugs(caller) == 0, "Caller's claimedDrugs not zero");

        // Check rule: referral's claimedDrugs increased by drugsUsed/5
        // drugsUsed was callerClaimedBefore because no new drugs since last collect
        uint256 expectedRefIncrease = callerClaimedBefore / 5;
        assertTrue(c.claimedDrugs(ref) == refClaimedBefore + expectedRefIncrease, "Referral bonus mismatch");
    }
}

